"""Learning Cards (PRD §11.2). Short, bilingual, beginner-friendly."""
from __future__ import annotations

CARDS: list[dict] = [
    {"id": "what_is_stock", "level": 1, "terms": ["market_cap"],
     "title_en": "What is a stock?", "title_zh": "什么是股票？",
     "body_en": "A stock (also called a share) is a tiny piece of ownership in a real company. If a company is split into 1,000 equal pieces and you own 10, you own 1% of it. When the business grows and earns more, each piece usually becomes more valuable over time.",
     "body_zh": "股票（也叫股份）是一家真实公司的一小部分所有权。如果一家公司被分成 1,000 份，你拥有 10 份，你就拥有它的 1%。当公司成长、赚钱更多时，每一份通常会随着时间变得更值钱。",
     "example_en": "Owning one Apple share means you own a very small slice of every iPhone sale Apple makes.",
     "example_zh": "拥有一股苹果股票，意味着你拥有苹果每一笔 iPhone 销售中极小的一部分。",
     "question_en": "Which company would you like to own a piece of, and why?", "question_zh": "你想拥有哪家公司的一部分？为什么？"},
    {"id": "what_is_company", "level": 1, "terms": ["revenue", "net_income"],
     "title_en": "What is a company?", "title_zh": "什么是公司？",
     "body_en": "A company is a group of people working together to sell products or services customers want. It spends money (salaries, materials, rent) and brings in money (sales). If it brings in more than it spends, it makes a profit.",
     "body_zh": "公司是一群人一起工作，向顾客提供他们需要的产品或服务。公司要花钱（工资、原材料、房租），也要赚钱（销售）。收入大于支出，公司就盈利。",
     "example_en": "A lemonade stand buys lemons and cups, sells lemonade, and keeps what is left over as profit.",
     "example_zh": "柠檬水摊买柠檬和杯子，卖出柠檬水，剩下的钱就是利润。",
     "question_en": "What does your favourite company sell, and who are its customers?", "question_zh": "你最喜欢的公司卖什么？它的顾客是谁？"},
    {"id": "revenue_vs_profit", "level": 1, "terms": ["revenue", "net_income", "gross_margin"],
     "title_en": "Revenue vs. Profit", "title_zh": "营收 vs. 利润",
     "body_en": "Revenue is all the money coming in from sales. Profit is what remains after paying every cost. A company can have huge revenue and still lose money if its costs are even bigger.",
     "body_zh": "营收是卖东西收到的全部钱；利润是扣除所有成本后剩下的钱。一家公司营收很大，但如果成本更大，依然会亏损。",
     "example_en": "Selling 100 cups at $2 = $200 revenue. If lemons, cups and sugar cost $150, profit is $50.",
     "example_zh": "卖 100 杯、每杯 2 美元 = 营收 200 美元。如果柠檬、杯子和糖花了 150 美元，利润就是 50 美元。",
     "question_en": "Why might a fast-growing company still not make a profit?", "question_zh": "为什么一家快速增长的公司可能仍然不赚钱？"},
    {"id": "eps", "level": 2, "terms": ["eps"],
     "title_en": "EPS: Earnings per Share", "title_zh": "每股收益（EPS）",
     "body_en": "EPS divides the company's profit by the number of shares. It shows how much profit belongs to each single share. Growing EPS over many years is often a sign of a healthy business.",
     "body_zh": "每股收益（Earnings per Share, EPS）等于公司利润除以股票数量，表示每一股分到多少利润。多年持续增长的 EPS 往往是健康企业的信号。",
     "example_en": "Profit $1,000 ÷ 100 shares = EPS of $10.", "example_zh": "利润 1,000 美元 ÷ 100 股 = 每股收益 10 美元。",
     "question_en": "What could make EPS rise even if profit stays the same?", "question_zh": "如果利润不变，什么情况会让 EPS 上升？（提示：股票数量）"},
    {"id": "pe", "level": 2, "terms": ["pe", "forward_pe"],
     "title_en": "P/E: Price-to-Earnings", "title_zh": "市盈率（P/E）",
     "body_en": "P/E = share price ÷ EPS. It tells you how many years of today's profit you are paying for. A higher P/E usually means investors expect faster growth — or that the stock is expensive. P/E alone never tells the full story.",
     "body_zh": "市盈率（Price-to-Earnings Ratio, P/E）= 股价 ÷ 每股收益，表示你在为多少年的当前利润付钱。市盈率高通常代表投资者预期增长更快——也可能说明股价偏贵。只看市盈率永远不够。",
     "example_en": "Price $100, EPS $5 → P/E of 20.", "example_zh": "股价 100 美元、每股收益 5 美元 → 市盈率 20。",
     "question_en": "Is a low P/E always a bargain? What could go wrong?", "question_zh": "低市盈率一定便宜吗？可能有什么陷阱？"},
    {"id": "fcf", "level": 2, "terms": ["fcf", "fcf_yield"],
     "title_en": "Free Cash Flow", "title_zh": "自由现金流",
     "body_en": "Profit on paper is not always cash in the bank. Free cash flow is the actual cash a business produces after investing in equipment and buildings. Companies with strong FCF can pay dividends, buy back shares or invest in growth.",
     "body_zh": "账面利润不一定等于银行里的现金。自由现金流（Free Cash Flow, FCF）是企业在投资设备和厂房之后真正产生的现金。自由现金流强的公司可以分红、回购股票或投资增长。",
     "example_en": "A bakery earns $50,000 cash but must spend $20,000 on a new oven: FCF is $30,000.",
     "example_zh": "面包店赚了 5 万美元现金，但要花 2 万美元买新烤箱：自由现金流是 3 万美元。",
     "question_en": "Why can profit growth differ from cash-flow growth?", "question_zh": "为什么利润增长不等于现金流增长？"},
    {"id": "dividend", "level": 1, "terms": ["dividend"],
     "title_en": "Dividends", "title_zh": "股息 / 分红",
     "body_en": "Some companies share part of their profit with owners as cash payments called dividends. Mature, stable companies often pay dividends; fast-growing companies often reinvest everything instead.",
     "body_zh": "一些公司会把部分利润以现金形式发给股东，这就是股息（Dividend）。成熟稳定的公司常常分红，快速成长的公司则通常把钱全部再投入业务。",
     "example_en": "Own 100 shares, dividend $0.50 per share → you receive $50.", "example_zh": "持有 100 股、每股分红 0.5 美元 → 你会收到 50 美元。",
     "question_en": "Would you prefer a company that pays dividends or one that reinvests? Why?", "question_zh": "你更喜欢分红的公司还是把钱再投资的公司？为什么？"},
    {"id": "etf", "level": 1, "terms": ["etf", "diversification"],
     "title_en": "ETFs: a basket of stocks", "title_zh": "ETF：一篮子股票",
     "body_en": "An Exchange-Traded Fund (ETF) holds many stocks at once and trades like a single stock. Buying one S&P 500 ETF share gives you a small piece of about 500 big US companies — instant diversification.",
     "body_zh": "交易所交易基金（Exchange-Traded Fund, ETF）一次持有很多股票，却能像一只股票一样买卖。买一股标普 500 ETF，就拥有了约 500 家美国大公司的一小部分——瞬间实现分散投资。",
     "example_en": "SPY and QQQ are well-known ETFs tracking the S&P 500 and Nasdaq-100.", "example_zh": "SPY 和 QQQ 是分别跟踪标普 500 和纳斯达克 100 的知名 ETF。",
     "question_en": "What are the trade-offs between one stock and an ETF?", "question_zh": "买单只股票和买 ETF 各有什么利弊？"},
    {"id": "diversification", "level": 1, "terms": ["diversification"],
     "title_en": "Diversification", "title_zh": "分散投资",
     "body_en": "Don't put all your eggs in one basket. Owning several companies in different industries means one bad surprise hurts less. Beginners especially benefit from not letting one position become too large.",
     "body_zh": "不要把鸡蛋放在同一个篮子里。持有不同行业的多家公司，意味着一次坏消息的伤害更小。初学者尤其要避免单一持仓过大。",
     "example_en": "If one of 10 equal holdings falls 50%, your portfolio drops only 5%.", "example_zh": "如果 10 个等额持仓中有一个下跌 50%，整个组合只下跌 5%。",
     "question_en": "What is the largest position in your simulated portfolio? Is that comfortable?", "question_zh": "你模拟盘里最大的持仓占多少？你觉得安心吗？"},
    {"id": "compounding", "level": 1, "terms": ["compound_interest"],
     "title_en": "Compound Interest", "title_zh": "复利",
     "body_en": "Compounding means your returns start earning returns of their own. The longer you wait, the bigger the effect. Time is the young investor's superpower.",
     "body_zh": "复利意味着你的收益会继续产生收益。时间越长，效果越惊人。时间是年轻投资者的超能力。",
     "example_en": "$1,000 growing 8% a year becomes about $2,159 in 10 years and $4,661 in 20 years.",
     "example_zh": "1,000 美元每年增长 8%，10 年后约 2,159 美元，20 年后约 4,661 美元。",
     "question_en": "Why does starting early matter so much?", "question_zh": "为什么越早开始越重要？"},
    {"id": "risk_return", "level": 1, "terms": ["volatility"],
     "title_en": "Risk and Return", "title_zh": "风险与收益",
     "body_en": "Higher potential returns almost always come with higher risk. Anyone promising big, fast, guaranteed profits is either wrong or not telling the truth. Good investors first ask: how much could I lose?",
     "body_zh": "更高的潜在收益几乎总是伴随着更高的风险。任何承诺快速、大额、保证收益的人，要么错了，要么没说实话。好的投资者首先问：我最多可能亏多少？",
     "example_en": "A stock that can rise 100% in a year can usually also fall 50%.", "example_zh": "一只一年能涨 100% 的股票，通常也可能跌 50%。",
     "question_en": "What would you do if a stock you own fell 30%?", "question_zh": "如果你持有的股票下跌 30%，你会怎么思考？"},
    {"id": "market_cap", "level": 1, "terms": ["market_cap"],
     "title_en": "Market Capitalization", "title_zh": "市值",
     "body_en": "Market cap is the share price times the number of shares. It is the price of the whole company. A $10 stock is not 'cheaper' than a $500 stock — what matters is the price of the whole business compared to its value.",
     "body_zh": "市值等于股价乘以股票总数，是整家公司的价格。10 美元的股票并不比 500 美元的股票“便宜”——关键是整家公司的价格和它的价值相比如何。",
     "example_en": "1 billion shares × $50 = $50 billion market cap.", "example_zh": "10 亿股 × 50 美元 = 500 亿美元市值。",
     "question_en": "Why is share price alone misleading?", "question_zh": "为什么只看股价会产生误导？"},
    {"id": "bull_bear", "level": 1, "terms": ["bull_bear"],
     "title_en": "Bulls and Bears", "title_zh": "牛与熊",
     "body_en": "A bull thinks prices will go up; a bear thinks they will go down. Good research always looks at both the bull case and the bear case before making a decision.",
     "body_zh": "“牛”认为价格会上涨，“熊”认为会下跌。好的研究总是在做决定前同时考虑乐观情景和悲观情景。",
     "example_en": "Bull: 'New products will grow sales.' Bear: 'Competitors will cut prices.'", "example_zh": "乐观：“新产品会带动销售增长。”悲观：“竞争对手会降价。”",
     "question_en": "For a company you like, what is the strongest bear argument?", "question_zh": "对你喜欢的公司，最有力的悲观理由是什么？"},
    {"id": "moat", "level": 2, "terms": ["moat"],
     "title_en": "Economic Moats", "title_zh": "护城河",
     "body_en": "Like a moat around a castle, a business moat keeps competitors out. Common moats: strong brands, network effects (more users make it more useful), low costs, and switching costs (it's a hassle to change).",
     "body_zh": "就像城堡外的护城河，企业的护城河能挡住竞争对手。常见护城河：强大品牌、网络效应（用户越多越有用）、成本优势、转换成本（换掉它很麻烦）。",
     "example_en": "A popular app where all your friends are is hard to leave — a network-effect moat.", "example_zh": "所有朋友都在用的应用很难离开——这就是网络效应护城河。",
     "question_en": "What moat does your favourite company have? Could it shrink?", "question_zh": "你最喜欢的公司有什么护城河？它会变窄吗？"},
    {"id": "valuation", "level": 2, "terms": ["valuation", "pe", "ps", "fcf_yield", "margin_of_safety"],
     "title_en": "Valuation: price vs. value", "title_zh": "估值：价格 vs. 价值",
     "body_en": "Price is what you pay; value is what you get. A great company can be a bad investment at the wrong price. Valuation tools like P/E, P/S and FCF yield must be judged together with growth, quality and risk.",
     "body_zh": "价格是你付出的，价值是你得到的。好公司在错误的价格买入，也可能是坏投资。市盈率、市销率、自由现金流收益率等估值工具，必须和增长、质量、风险一起判断。",
     "example_en": "Paying $30 for something worth $20 loses money even if the item is excellent.", "example_zh": "花 30 美元买一个只值 20 美元的东西，哪怕东西很好也会亏钱。",
     "question_en": "Why can a great company still be a bad investment?", "question_zh": "为什么优秀的公司在错误的价格下仍可能是糟糕的投资？"},
    {"id": "volatility", "level": 2, "terms": ["volatility", "beta"],
     "title_en": "Volatility", "title_zh": "波动性",
     "body_en": "Prices wiggle every day. Volatility measures how big those wiggles are. Short-term moves are often noise; long-term results follow the business.",
     "body_zh": "价格每天都在波动。波动性衡量这些波动有多大。短期涨跌往往是噪音，长期结果取决于企业本身。",
     "example_en": "A stock can drop 5% in a day on no real news and recover the next week.", "example_zh": "一只股票可能在没有实质消息的情况下一天下跌 5%，下周又涨回来。",
     "question_en": "How can a journal help you stay calm during big price swings?", "question_zh": "投资日志如何帮你在大幅波动时保持冷静？"},
    {"id": "thesis", "level": 2, "terms": [],
     "title_en": "Writing an Investment Thesis", "title_zh": "写一份投资逻辑（Investment Thesis）",
     "body_en": "A thesis is your written reason for owning a company: why it will be more valuable, what the biggest risk is, and what would change your mind. Writing it down helps you learn whether you were right for the right reasons.",
     "body_zh": "投资逻辑（Investment Thesis）是你持有一家公司的书面理由：为什么它会更有价值、最大的风险是什么、什么会让你改变想法。写下来能帮你判断自己是否“因为正确的理由而正确”。",
     "example_en": "'I own Costco because members renew every year; the risk is slowing store growth; I'd rethink if renewal rates fall.'",
     "example_zh": "“我持有 Costco，因为会员每年续费；风险是开店速度放缓；如果续费率下降，我会重新思考。”",
     "question_en": "Can you explain your biggest holding in two minutes?", "question_zh": "你能在两分钟内讲清楚你最大持仓的投资逻辑吗？"},
    {"id": "mr_market", "level": 2, "terms": [],
     "title_en": "Mr. Market", "title_zh": "市场先生",
     "body_en": "Imagine a moody business partner who offers to buy or sell your share every day at a different price. Some days he is euphoric, some days gloomy. You can use his offers — but you never have to follow his mood.",
     "body_zh": "想象一个情绪多变的合伙人，每天都以不同价格提出买你或卖给你股份。有时他兴奋，有时他沮丧。你可以利用他的报价，但永远不必跟随他的情绪。",
     "example_en": "A price drop without any change in the business can be an opportunity, not a reason to panic.",
     "example_zh": "企业本身没有变化时的价格下跌，可能是机会，而不是恐慌的理由。",
     "question_en": "When did a price move make you feel emotional? What did the business actually do?", "question_zh": "什么时候价格波动让你情绪激动？当时公司本身发生了什么？"},
    {"id": "financial_statements", "level": 3, "terms": ["revenue", "net_income", "fcf"],
     "title_en": "The three financial statements", "title_zh": "三张财务报表",
     "body_en": "Income statement: revenue, costs and profit over a period. Balance sheet: what the company owns and owes at a point in time. Cash flow statement: where cash actually came from and went. Together they tell the business's story in numbers.",
     "body_zh": "利润表：一段时间内的营收、成本和利润。资产负债表：某一时刻公司拥有什么、欠了什么。现金流量表：现金实际从哪里来、到哪里去。三张表一起用数字讲述企业的故事。",
     "example_en": "A company can show profit on the income statement but run low on cash if customers pay late.",
     "example_zh": "如果客户付款慢，公司可能在利润表上盈利，但现金却很紧张。",
     "question_en": "Which statement would you check first to see if a company might run out of money?", "question_zh": "想看公司会不会缺钱，你会先看哪张报表？"},
    {"id": "debt", "level": 3, "terms": [],
     "title_en": "Debt: a double-edged sword", "title_zh": "负债：一把双刃剑",
     "body_en": "Borrowing can help a company grow faster, but interest must be paid in good times and bad. Too much debt can sink even a good business during a downturn. Compare cash with total debt.",
     "body_zh": "借钱能帮公司更快成长，但无论好坏年景都要付利息。负债过多时，即使是好企业也可能在经济下行时陷入困境。可以对比现金和总负债。",
     "example_en": "A company with $50B cash and $10B debt is in a very different position from one with $1B cash and $30B debt.",
     "example_zh": "一家有 500 亿现金、100 亿负债的公司，和一家只有 10 亿现金却有 300 亿负债的公司，处境完全不同。",
     "question_en": "Why is borrowing money to buy stocks especially risky for individuals?", "question_zh": "为什么个人借钱买股票特别危险？"},
    {"id": "benchmark", "level": 2, "terms": ["benchmark"],
     "title_en": "Benchmarks", "title_zh": "基准",
     "body_en": "To know if your choices are working, compare with a simple alternative like an S&P 500 ETF. Beating the market over the long run is hard; learning why is the real goal.",
     "body_zh": "想知道自己的选择是否有效，就和简单的替代方案比较，比如标普 500 ETF。长期跑赢市场很难；弄清楚原因才是真正的目标。",
     "example_en": "If your portfolio rose 8% but the S&P 500 rose 12%, a simple ETF would have done better.",
     "example_zh": "如果你的组合涨了 8%，而标普 500 涨了 12%，买简单的 ETF 会更好。",
     "question_en": "What benchmark makes sense for your portfolio?", "question_zh": "什么基准适合你的组合？"},
    {"id": "biases", "level": 3, "terms": [],
     "title_en": "Thinking traps (biases)", "title_zh": "思维陷阱（认知偏差）",
     "body_en": "Our brains trick us: we follow the crowd (herding), believe we know more than we do (overconfidence), and hold losers hoping to 'get even' (loss aversion). Naming these traps helps avoid them.",
     "body_zh": "大脑会欺骗我们：随大流（从众）、高估自己（过度自信）、死守亏损股票想“回本”（损失厌恶）。给这些陷阱起个名字，能帮你避开它们。",
     "example_en": "Buying a stock only because everyone at school talks about it is herding.", "example_zh": "只因为学校里大家都在谈论就买一只股票，这就是从众。",
     "question_en": "Which thinking trap do you find hardest to avoid?", "question_zh": "你觉得哪个思维陷阱最难避免？"},
    {"id": "long_term", "level": 1, "terms": ["compound_interest"],
     "title_en": "Why long-term thinking wins", "title_zh": "为什么长期思维更有优势",
     "body_en": "Over days, prices are driven by news and emotions. Over years, they follow a company's earnings and cash flow. Trading a lot usually adds costs and mistakes; patience lets compounding work.",
     "body_zh": "短期内，价格由新闻和情绪驱动；长期来看，价格跟随公司的利润和现金流。频繁交易通常会增加成本和错误；耐心才能让复利发挥作用。",
     "example_en": "Many great long-term investments had several 30% drops along the way.", "example_zh": "许多伟大的长期投资，途中都经历过几次 30% 的下跌。",
     "question_en": "How long do you plan to hold your current positions, and why?", "question_zh": "你打算持有现在的仓位多久？为什么？"},
    {"id": "orders", "level": 1, "terms": ["market_order"],
     "title_en": "How a simulated trade works", "title_zh": "模拟交易是怎么运作的",
     "body_en": "In this app you place a market order: you buy or sell right away at the latest available price. Buying uses virtual cash; selling returns cash. No real money is ever involved.",
     "body_zh": "在本应用中，你下的是市价单：按最新可用价格立即买入或卖出。买入会用掉虚拟现金，卖出会拿回现金。全程不涉及任何真实资金。",
     "example_en": "Buy 10 shares at $200 → cash falls by $2,000 and you now own 10 shares.", "example_zh": "以 200 美元买入 10 股 → 现金减少 2,000 美元，你持有 10 股。",
     "question_en": "Before your next trade, can you write one sentence on why?", "question_zh": "下一次交易前，你能先写一句为什么吗？"},
]

